function smoothClosed(pp) {
  const n = pp.length;
  let d = `M${pp[0][0].toFixed(1)},${pp[0][1].toFixed(1)}`;
  for (let i = 0; i < n; i++) {
    const p0 = pp[(i - 1 + n) % n],
      p1 = pp[i],
      p2 = pp[(i + 1) % n],
      p3 = pp[(i + 2) % n];
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6],
      c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${c1[0].toFixed(1)},${c1[1].toFixed(1)} ${c2[0].toFixed(1)},${c2[1].toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d + "Z";
}
/* zasahuje lomená čára (prstenec, řeka) do kreslené oblasti v? (obálka v jednotkách mapy se spočítá jednou) – mapa od Baltu k Jadranu
   má dlouhé pobřeží a řeky daleko od výřezu; kreslit je mimo výřez zdržuje telefon (2026-10-27) */
const OBALKY = new WeakMap();
function vKresbe(r, v) {
  let o = OBALKY.get(r);
  if (!o) {
    o = [Infinity, Infinity, -Infinity, -Infinity];
    for (const c of r) {
      const [x, y] = P(...c);
      o = [Math.min(o[0], x), Math.min(o[1], y), Math.max(o[2], x), Math.max(o[3], y)];
    }
    OBALKY.set(r, o);
  }
  return o[2] >= v[0] - 20 && o[0] <= v[0] + v[2] + 20 && o[3] >= v[1] - 20 && o[1] <= v[1] + v[3] + 20;
}
