        most: t => `M${f1(-3.6 * t)},${f1(1.6 * t)}Q0,${f1(-2.8 * t)} ${f1(3.6 * t)},${f1(1.6 * t)}M${f1(-4 * t)},${f1(-0.4 * t)}H${f1(4 * t)}`,
